}

func BlobRPCMinValidSlot(current primitives.Slot) (primitives.Slot, error) {
    if params.BeaconConfig().DenebForkEpoch == math.MaxUint64 {
        return primitives.Slot(math.MaxUint64), nil
    }
    minReqEpochs := params.BeaconConfig().MinEpochsForBlobsSidecarsRequest
    currEpoch := slots.ToEpoch(current)
    minStart := params.BeaconConfig().DenebForkEpoch
    if currEpoch > minReqEpochs && currEpoch-minReqEpochs > minStart {
        minStart = currEpoch - minReqEpochs
    }
    return slots.EpochStart(minStart)
}

func validateBlobsByRange(r *pb.BlobSidecarsByRangeRequest, current primitives.Slot) (rangeParams, error) {
    if r.Count == 0 { return rangeParams{}, errors.Wrap(...) }
    rp := rangeParams{start: r.StartSlot, size: r.Count}
    if rp.start > current { return rangeParams{start: current, end: current, size: 0}, nil }
    // ... overflow checks, min/max slot validation ...
    minStartSlot, err := BlobRPCMinValidSlot(current)
    if rp.start < minStartSlot { rp.start = minStartSlot }
    if rp.end > current { rp.end = current }
    // ... batch limit checks ...
}
```

**RPC handler registration** (rpc.go):
- BlobSidecarsByRange is registered at ALL fork levels: Deneb, Electra, and Fulu
- The same handler s.blobSidecarsByRangeRPCHandler is used for all

**Key observations**:
- There is NO Fulu-specific epoch check in validateBlobsByRange or BlobRPCMinValidSlot
- BlobRPCMinValidSlot uses DenebForkEpoch as lower bound and current epoch as upper bound
- There is NO FuluForkEpoch upper bound to prevent serving post-Fulu data
- The handler is still registered and active after Fulu fork
- Peer scoring: downscorePeer is called for validation errors ("blobSidecarsByRangeRpcHandlerValidationError")

